class Solution {
public:
    vector<string> mostVisitedPattern(vector<string>& username, vector<int>& timestamp, vector<string>& website) {
        int n = username.size();
        vector<tuple<int, string, string>> visits;
        for (int i = 0; i < n; ++i) {
            visits.push_back({timestamp[i], username[i], website[i]});
        }
        sort(visits.begin(), visits.end());

        unordered_map<string, vector<string>> user_history;
        for (const auto& [t, u, w] : visits) {
            user_history[u].push_back(w);
        }

        map<vector<string>, int> pattern_counts;
        for (const auto& [u, history] : user_history) {
            int sz = history.size();
            set<vector<string>> unique_patterns;
            for (int i = 0; i < sz; ++i) {
                for (int j = i + 1; j < sz; ++j) {
                    for (int k = j + 1; k < sz; ++k) {
                        unique_patterns.insert({history[i], history[j], history[k]});
                    }
                }
            }
            for (const auto& pat : unique_patterns) {
                pattern_counts[pat]++;
            }
        }

        int max_cnt = 0;
        vector<string> best;
        for (const auto& [pat, cnt] : pattern_counts) {
            if (cnt > max_cnt) {
                max_cnt = cnt;
                best = pat;
            }
        }
        return best;
    }
};

import java.util.*;

class Solution {
    public List<String> mostVisitedPattern(String[] username, int[] timestamp, String[] website) {
        int n = username.length;
        List<int[]> order = new ArrayList<>();
        for (int i = 0; i < n; i++) order.add(new int[]{timestamp[i], i});
        order.sort(Comparator.comparingInt(a -> a[0]));

        Map<String, List<String>> userHistory = new HashMap<>();
        for (int[] item : order) {
            int i = item[1];
            userHistory.computeIfAbsent(username[i], k -> new ArrayList<>()).add(website[i]);
        }

        Map<String, Integer> counts = new HashMap<>();
        int maxCnt = 0;
        String bestPatternStr = "";

        for (List<String> history : userHistory.values()) {
            int sz = history.size();
            Set<String> unique = new HashSet<>();
            for (int i = 0; i < sz; i++) {
                for (int j = i + 1; j < sz; j++) {
                    for (int k = j + 1; k < sz; k++) {
                        unique.add(history.get(i) + " " + history.get(j) + " " + history.get(k));
                    }
                }
            }
            for (String pat : unique) {
                int c = counts.getOrDefault(pat, 0) + 1;
                counts.put(pat, c);
                if (c > maxCnt || (c == maxCnt && pat.compareTo(bestPatternStr) < 0)) {
                    maxCnt = c;
                    bestPatternStr = pat;
                }
            }
        }
        return Arrays.asList(bestPatternStr.split(" "));
    }
}

var mostVisitedPattern = function(username, timestamp, website) {
    const n = username.length;
    const visits = [];
    for (let i = 0; i < n; i++) {
        visits.push({ t: timestamp[i], u: username[i], w: website[i] });
    }
    visits.sort((a, b) => a.t - b.t);

    const userHistory = new Map();
    for (const { u, w } of visits) {
        if (!userHistory.has(u)) userHistory.set(u, []);
        userHistory.get(u).push(w);
    }

    const patternCounts = new Map();
    for (const history of userHistory.values()) {
        const sz = history.length;
        const unique = new Set();
        for (let i = 0; i < sz; i++) {
            for (let j = i + 1; j < sz; j++) {
                for (let k = j + 1; k < sz; k++) {
                    unique.add(history[i] + '###' + history[j] + '###' + history[k]);
                }
            }
        }
        for (const pat of unique) {
            patternCounts.set(pat, (patternCounts.get(pat) || 0) + 1);
        }
    }

    let best = '';
    let maxCnt = 0;
    for (const [pat, cnt] of patternCounts.entries()) {
        if (cnt > maxCnt || (cnt === maxCnt && pat < best)) {
            maxCnt = cnt;
            best = pat;
        }
    }
    return best.split('###');
};
